WITH valid_departments AS (SELECT *, COALESCE(location, 'Unknown') AS location_filled FROM departments WHERE location IN ('Bangkok', 'New York', 'Chiang Mai') AND budget BETWEEN 1226000 AND 2501000), location_group_summary AS (SELECT CASE WHEN location IN ('Singapore', 'Bangkok') THEN 'priority' ELSE 'other' END AS location_group, ROUND(STDDEV(budget), 2) AS stddev_budget, SUM(budget) AS total_budget FROM valid_departments GROUP BY CASE WHEN location IN ('Singapore', 'Bangkok') THEN 'priority' ELSE 'other' END) SELECT * FROM location_group_summary WHERE stddev_budget > 44 ORDER BY location_group DESC, stddev_budget DESC LIMIT 1
